#include "domain/native_archipelago.hpp"
#include "domain/water_locomotion.hpp"
#include "domain/locomotion_pace.hpp"
#include "domain/body_terrain_support.hpp"
#include "domain/environmental_exposure.hpp"
#include <iostream>
using namespace stalthos;
int main(){world::NativeArchipelago field(42);auto route=*field.firstCrossing();const double pace=domain::LocomotionPace::calculate(.16128,2,domain::LocomotionPace::Intent::Forward).signedSpeed;auto support=domain::calculateTerrainSupport(route.start.x,route.start.z,route.yaw,.5,.25,[&](double x,double z){return field.triangleHeight(x,z);});needs::NeedsCore needs(HeroSpecies::Smalltrotter);environment::BodyWeatherResponse weather;double d=0,t=0;unsigned dryFails=0,wadeFails=0,swim=0;double maxGroundSlope=0;bool landed=false;for(;t<600;t+=.01){double x=route.start.x+std::sin(route.yaw)*d,z=route.start.z+std::cos(route.yaw)*d;auto water=domain::waterMotion(field.triangleHeight(x,z),true,needs.fatigue());auto stance=domain::calculateTerrainSupport(x,z,route.yaw,.5,.25,[&](double a,double b){return field.triangleHeight(a,b);});if(water.mode!=domain::WaterMode::Swimming){for(double bulk:{.45,.7,1.0}){auto localStance=domain::calculateTerrainSupport(x,z,route.yaw,.5*bulk,.25*bulk,[&](double a,double b){return field.triangleHeight(a,b);});maxGroundSlope=std::max(maxGroundSlope,localStance.slopeAngleRadians);if(!localStance.supported){if(water.mode==domain::WaterMode::Land)++dryFails;else ++wadeFails;}}}if(water.mode==domain::WaterMode::Swimming)++swim;if(swim&&field.landRegion(x,z,field.triangleHeight(x,z))==1003&&field.triangleHeight(x,z)>.4&&std::hypot(x-route.end.x,z-route.end.z)<8){landed=true;break;}double speed=water.mode==domain::WaterMode::Swimming?2.2*water.speedFactor:pace*water.speedFactor;if(t>=2)d+=speed*.01;auto local=weather.advance(environment::sample(42,1001,t,{0,0,.35,0}),.01,environment::routeWindShelter(x,z));domain::applySwimming(needs,water,.01,true);needs.advance({.01,.01});environment::applyExposure(needs,local,.01,true);if(t>158.17&&t<158.19)std::cout<<"AT158 t="<<t<<" d="<<d<<" fatigue="<<needs.fatigue()<<" x="<<x<<" z="<<z<<"\n";}
 std::cout<<"REAL_OWNER_ROUTE land_pace="<<pace<<" start_slope="<<support.slopeAngleRadians<<" start_supported="<<support.supported<<" landed="<<landed<<" seconds="<<t<<" distance="<<d<<" fatigue="<<needs.fatigue()<<" dry_failure_steps="<<dryFails<<" wade_failure_steps="<<wadeFails<<" max_ground_slope="<<maxGroundSlope<<" swim_steps="<<swim<<"\n";return (!landed||dryFails||wadeFails||!support.supported||t>240)?1:0;}


